-- Scoped cosmetic joints return to the skin's held grip after playback.
local Attachment={}
function Attachment.bind(r,life,tool,assembly,spec,animator)
    local weld=assembly.rootWeld local manager=r.cosmetics
    if not weld or not animator or not manager then return end
    local base,rest=weld.Part0,weld.C0
    local char=r.ctx.player.Character local hand=char and (char:FindFirstChild("RightHand")or char:FindFirstChild("Right Arm"))
    local handle=tool:FindFirstChild("Handle")if not hand or not handle then return end
    local held
    local active,proxies={},{}local binding
