        local avatar=r.clones and r.clones.avatar
        if avatar and avatar.weapon and avatar.weapon.RefreshPose then avatar.weapon:RefreshPose()end
    end
    local function restore()
        if binding then binding:Cleanup()binding=nil refreshClone()end
    end
    local function update()
        local latest,stamp=nil,-1
        for track,row in pairs(active)do if row.ready and track.IsPlaying and row.serial>stamp then latest,stamp=row,row.serial end end
        restore()
        if latest then binding=life:Scope()binding:SetProperty(weld,"Part0",latest.proxy)binding:SetProperty(weld,"C0",latest.offset)end
    end
    local function proxy(name)
        if proxies[name]then return proxies[name]end
        local part=life:Own(Instance.new("Part"))part.Name=name part.Size=Vector3.new(.001,.001,.001)part.Transparency=1 part.CanCollide=false part.CanTouch=false part.CanQuery=false part.Massless=true part.CFrame=hand.CFrame part.Parent=tool
