        local grip=typeof(tool.Grip)=="CFrame"and tool.Grip or CFrame.identity
        local point=hand:FindFirstChild("RightGripAttachment")local handToHandle=(point and point.CFrame or CFrame.new(0,-hand.Size.Y/2,0))*grip:Inverse()
        for _,joint in ipairs(hand:GetChildren())do if joint:IsA("JointInstance")and joint.Part0==hand and joint.Part1==handle then handToHandle=joint.C0*joint.C1:Inverse()break end end
        local relative=handle.CFrame:ToObjectSpace(base.CFrame)
        assert(relative.Position.Magnitude<32,"Native held geometry has not settled")
        return handToHandle*relative*rest
    end
    local function ensureHeld()
        if held then return held end
        local point=assert(hand:FindFirstChild("RightGripAttachment"),"Hand grip attachment unavailable")
        local ring=assert(assembly.root and assembly.root:FindFirstChild("RingFX"),"Cyan ring attachment unavailable")
        -- Roll Cyan around its long mesh axis so the hook curves upward.
        -- Rotate around the authored ring, keeping it at this body's hand grip.
        held=CFrame.new(point.Position)*nativeGrip().Rotation*CFrame.Angles(math.pi,0,0)*CFrame.new(-ring.Position)
