        if spec.gripMode=="ring"then return ensureHeld()end
        if spec.profile and name=="Handle.R"then local angles=spec.profile.rotationoffset return CFrame.new(spec.profile.positionoffset)*CFrame.Angles(math.rad(angles.X),math.rad(angles.Y),math.rad(angles.Z))end
        return nativeGrip()
    end
    if spec.gripMode=="ring"then
        local once=life:Scope()
        once:Connect(r.ctx.run.PostSimulation,function()
            once:Cleanup()if not life.Alive then return end
            local ok,err=pcall(ensureHeld)
            r.Errors['skin-attachment:'..tool.Name]=not ok and tostring(err)or nil
        end)
    end
    local function observe(track)
        local record=manager.tracks[track]if not record or record.tool~=tool or active[track]then return end
        local info=SkinAnimationCatalog.info[record.id]if not info or not info.body then return end
        local name for _,node in ipairs(info.hand or {})do if node~="Handle"then name=node break end end
        if not name then return end
