local SkinRigPlayback = (function()
-- Only the inert geometry created by SkinAssembly. Native game scripts never run here.
local Rig={}
function Rig.equip(r,life,tool,assembly,spec)
    local copy=assembly.copy local manager=r.cosmetics local plan=spec.plan
    if not copy or not manager or not(plan.meshEquip or plan.meshIdle)then return end
    local roles={}local key="skin-rig:"..tool.Name r.Errors[key]=nil
    life:Defer(function()for role in pairs(roles)do manager:Stop(tool,role)end r.Errors[key]=nil end)
    local animators=copy:QueryDescendants("Animator")
    if #animators==0 and (#copy:QueryDescendants("Motor6D")>0 or #copy:QueryDescendants("Bone")>0)then
        local controller=life:Own(Instance.new("AnimationController"))controller.Name="ReforgedSkinController"controller.Parent=copy
        local animator=life:Own(Instance.new("Animator"))animator.Parent=controller animators={animator}
    end
    local function best(id)
        local info=SkinAnimationCatalog.info[id]if not info or info.body then return nil end
        local target,score=nil,0
        for _,animator in ipairs(animators)do
            local root=animator.Parent.Parent local names={}
            for _,node in ipairs(root:QueryDescendants("Bone, BasePart"))do names[node.Name]=true end
            local matched=0 for _,name in ipairs(info.poses or {})do if name~="RootPart"and name~="Root"and name~="HumanoidRootPart"and names[name]then matched+=1 end end
            if matched>score then target,score=animator,matched end
        end
        return target
    end
    local function play(role,id)
        if not id then return nil end
        local animator=best(id)
        if not animator then r.Errors["skin-rig:"..tool.Name]="No compatible cosmetic rig for "..id return nil end
        local track=manager:Animation(animator,{AnimationId="rbxassetid://"..id},tool,true,role,SkinAnimationCatalog.info[id])
        roles[role]=true
        return track
    end
    local equip=play("mesh-equip",plan.meshEquip)
    local function idle()if life.Alive then play("mesh-idle",plan.meshIdle)end end
    if equip and not equip.Looped and plan.meshIdle then manager:OnFinish(equip,life,idle)else idle()end
    life:Connect(tool:GetAttributeChangedSignal("Attacking"),function()
        local state=tool:GetAttribute("Attacking")local id,role
        if state=="Slash"and plan.normal then id=plan.normal[1]role="mesh-normal"
        elseif state=="Hold"then id=plan.charge role="mesh-charge"
        elseif state=="HoldSlash"then id=plan.heavy role="mesh-heavy"end
        local info=id and SkinAnimationCatalog.info[id]
        if info and not info.body then play(role,id)end
    end)
end
return Rig

end)()
local SkinRestGrip = (function()
-- Photo-calibrated resting adapters, separate from each skin's original pullout.
-- Grip points were measured against native flat asset views, not private scripts.
local Rest={profiles={
    ["Galaxy Karambit"]={point=Vector3.new(.14,-.40,0),rotation=CFrame.Angles(0,0,math.pi),staticRest=true},
    WinterKarambit={point=Vector3.new(-.28,.46,0),rotation=CFrame.Angles(0,0,math.rad(-60))},
    RoseKarambit={point=Vector3.new(-.38,.17,0),rotation=CFrame.Angles(0,0,math.rad(-60))},
    ["RGB Karambit"]={point=Vector3.new(0,-.64,-.715),rotation=CFrame.Angles(0,0,math.rad(120))*CFrame.Angles(0,math.pi/2,0),cyan=true},
}}
local function objects(copy)
    local list=copy:QueryDescendants("BasePart, ParticleEmitter, Trail, Beam, Light")
    if copy:IsA("BasePart")then table.insert(list,1,copy)end return list
end
local function hide(scope,copy)
    for _,o in ipairs(objects(copy))do if o:IsA("BasePart")then scope:SetProperty(o,"Transparency",1)else scope:SetProperty(o,"Enabled",false)end end
end
function Rest.equip(r,life,tool,assembly,spec,animator)
    local profile=spec.restGrip local target=assembly.rest or assembly local weld=target.rootWeld local manager=r.cosmetics
    if not profile or not weld or not manager then return end
    local char=r.ctx.player.Character local hand=char and (char:FindFirstChild("RightHand")or char:FindFirstChild("Right Arm"))
    local point=hand and hand:FindFirstChild("RightGripAttachment")if not point then return end
    local base,original=weld.Part0,weld.C0 local pose local playing,seen,animators={},{},{}local binding,hidden local initialized=false
    local function hideRest()
        if assembly.rest and not hidden then hidden=life:Scope()hide(hidden,target.copy)end
    end
    local function release()
        if binding then binding:Cleanup()binding=nil end hideRest()
    end
    local function grip()
        local rotation=point.CFrame.Rotation*profile.rotation
        if profile.cyan then
            local data=r.skinCatalog and r.skinCatalog["[Knife]"]and r.skinCatalog["[Knife]"].CyanKarambit
            assert(data and typeof(data.CFrame)=="CFrame","Cyan reference grip unavailable")
            local handle=assert(tool:FindFirstChild("Handle"))local handToHandle=point.CFrame*tool.Grip:Inverse()
            for _,joint in ipairs(hand:GetChildren())do if joint:IsA("JointInstance")and joint.Part0==hand and joint.Part1==handle then handToHandle=joint.C0*joint.C1:Inverse()break end end
            local relative=handle.CFrame:ToObjectSpace(base.CFrame)assert(relative.Position.Magnitude<32,"Native grip has not settled")
            rotation=(handToHandle*relative*data.CFrame).Rotation*CFrame.Angles(math.pi,0,0)*profile.rotation
        end
        return CFrame.new(point.Position)*rotation*CFrame.new(-profile.point)
    end
    local function update()
        if not life.Alive or not initialized then return end
        if next(playing)then release()return end
        if binding then return end
        local ok,value=pcall(grip)
        if not ok then r.Errors['skin-rest:'..tool.Name]=tostring(value)return end
        pose=value r.Errors['skin-rest:'..tool.Name]=nil
        if hidden then hidden:Cleanup()hidden=nil end
        binding=life:Scope()
        binding:SetProperty(weld,"Part0",hand)binding:SetProperty(weld,"C0",pose)
        if assembly.rest then hide(binding,assembly.copy)end
        local avatar=r.clones and r.clones.avatar if avatar and avatar.weapon and avatar.weapon.RefreshPose then avatar.weapon:RefreshPose()end
    end
    local function observe(track)
        if seen[track]then return end
        local record=manager.tracks[track]if not record or record.tool~=tool or track.Looped then return end
        seen[track]=true playing[track]=true release()
        manager:OnFinish(track,life,function()playing[track]=nil seen[track]=nil update()end)
    end
    local function watch(o)
        if o:IsA("Animator")and not animators[o]then animators[o]=true life:Connect(o.AnimationPlayed,observe)end
    end
    hideRest()if animator then watch(animator)end
    for _,o in ipairs(assembly.copy:QueryDescendants("Animator"))do watch(o)end
    life:Connect(assembly.copy.DescendantAdded,watch)
    local once=life:Scope()once:Connect(r.ctx.run.PostSimulation,function()
        once:Cleanup()for track in pairs(manager.tracks)do observe(track)end initialized=true update()
    end)
    life:Defer(function()table.clear(playing)table.clear(seen)table.clear(animators)r.Errors['skin-rest:'..tool.Name]=nil end)
end
return Rest

end)()
local SkinCosmetics = (function()
-- Scoped equivalents of the references' skin metadata/equip handling.
-- Never executes SkinScripts or changes native gun modules/animation flags.
local Cosmetics={}
function Cosmetics.shotAttachments(part)
    local beam=part:FindFirstChildOfClass("Beam")
    if beam and beam.Attachment0 and beam.Attachment1 then return beam.Attachment0,beam.Attachment1 end
    local list={}for _,o in ipairs(part:GetChildren())do if o:IsA("Attachment")then list[#list+1]=o end end
    return list[1],list[2]
end
function Cosmetics.attribute(life,object,key,value)
    local before=object:GetAttribute(key)local writing=false
    local function apply()
        if not writing and object:GetAttribute(key)~=value then writing=true object:SetAttribute(key,value)writing=false end
    end
    life:Defer(function()if object:GetAttribute(key)==value then object:SetAttribute(key,before)end end)
    life:Connect(object:GetAttributeChangedSignal(key),apply)apply()
end
local aliases={
    ["[Knife]"]={"knife","Knife","KnifeEquip"},["[Double-Barrel SG]"]={"DB"},["[Drum-Shotgun]"]={"Drum"},
    ["[Revolver]"]={"Rev","Revolver","RevEquip"},["[Rifle]"]={"Rifle"},["[AR]"]={"AR"},["[AUG]"]={"AUG"},
}
local function child(parent,name)return parent and parent:FindFirstChild(name)end
local function firstSound(parent,names)
    for _,name in ipairs(names)do local o=parent and parent:FindFirstChild(name,true)if o and o:IsA("Sound")then return o end end
end
local function named(parent,name)
    if not parent then return nil end
    local direct=parent:FindFirstChild(name)if direct then return direct end
    local normalized=name:lower():gsub("[^%w]","")local match
    for _,o in ipairs(parent:GetChildren())do if o.Name:lower():gsub("[^%w]","")==normalized then if match then return nil end match=o end end
    return match
end
function Cosmetics.asset(id)return id and {AnimationId="rbxassetid://"..id}or nil end
function Cosmetics.info(id)return SkinAnimationCatalog and SkinAnimationCatalog.info[id]or nil end
function Cosmetics.resolve(r,tool,name)
    local assets=r.ctx.replicated:FindFirstChild("SkinAssets")local folder=named(child(assets,"SkinScriptsStorage"),name)
    local result={profile=tool.Name=="[Knife]"and KnifeProfiles[name]or nil}
    -- User reference: Cyan is held by its ring, with the native blade direction.
    -- The catalogue preview translation does not put that ring in the hand.
    if tool.Name=="[Knife]"and name=="CyanKarambit"then result.gripMode="ring"end
    if tool.Name=="[Knife]"and SkinRestGrip then result.restGrip=SkinRestGrip.profiles[name]end
    local plan=SkinAnimationCatalog and SkinAnimationCatalog.rows[tool.Name]and SkinAnimationCatalog.rows[tool.Name][name]
    result.plan=plan or {}result.animation=plan and Cosmetics.asset(plan.equip)
    -- Legacy fixture/new-client fallback only when no audited catalogue exists.
    -- KnifeSkinAnimation is attack data, never a pullout fallback.
    if not SkinAnimationCatalog then
        for _,key in ipairs(aliases[tool.Name]or {tool.Name:gsub("[%[%]]","")})do local a=child(folder,key)if a and a:IsA("Animation")then result.animation=a break end end
        if not result.animation and result.profile and result.profile.animationid~=""then result.animation={AnimationId=result.profile.animationid}end
    end
    if plan and plan.rig then
        local rig=child(child(assets,"SkinScriptsStorage"),plan.rig.family)
        for key in plan.rig.path:gmatch("[^%.]+")do rig=child(rig,key)end
        if rig and rig:IsA("Model")then result.rig=rig end
    end
    local script=named(child(assets,"SkinScripts"),name)
    local knifeHas=r.skinCatalog and r.skinCatalog["[Knife]"]and r.skinCatalog["[Knife]"][name]
    if tool.Name=="[Knife]"or not knifeHas or result.animation or plan and (plan.meshEquip or plan.meshIdle)then
        result.equip=firstSound(script,{"Equip","EquipSFX","EquipSFX1","On"})
        if tool.Name=="[Knife]"then result.equip=firstSound(script,{"TantoEquip","Equip","EquipSFX","EquipSFX1","On"})
        elseif tool.Name=="[Revolver]"then result.equip=firstSound(script,{"RevEquip","Equip","EquipSFX","EquipSFX1","On"})end
