-- User-approved source-backed effects; original UE effect definitions unrecovered.
local Effects={name="Character effects"}
local r6={UpperTorso="Torso",LowerTorso="Torso",LeftUpperArm="Left Arm",RightUpperArm="Right Arm",LeftUpperLeg="Left Leg",RightUpperLeg="Right Leg",Torso="UpperTorso"}
local function bodyPart(char,name)return char:FindFirstChild(name)or r6[name]and char:FindFirstChild(r6[name])end
local function edited(r,prefix,kind)
    for i=1,3 do local _,_,custom=r:Color(prefix..kind.."_color"..i)if custom then return true end end
    return false
end
local function valueAt(sequence,time)
    local points=sequence.Keypoints
    for i=2,#points do local right,left=points[i],points[i-1]
        if time<=right.Time then return left.Value+(right.Value-left.Value)*(time-left.Time)/(right.Time-left.Time)end
    end
    return points[#points].Value
end
