end
local function teleport(r)
    local selected
    for _,player in ipairs(r.ctx.players:GetPlayers())do
        if player~=r.ctx.player and player.Name==r:Value("selected_player_dropdown")then selected=player break end
    end
    assert(selected and selected.Parent==r.ctx.players,"Select an available player first")
    local target=selected.Character
    local targetRoot=target and target:FindFirstChild("HumanoidRootPart")
    local targetHum=target and target:FindFirstChildOfClass("Humanoid")
    assert(target and target.Parent and targetRoot and targetRoot:IsA("BasePart")and targetHum and targetHum.Health>0,"Selected player's character is unavailable")
