    local pose=CFrame.new(destination)*root.CFrame.Rotation
    local pivot=pose*root.CFrame:Inverse()*actor:GetPivot()
    -- Fly holds a captured CFrame. Recreate only that active scope at the new
    -- location so its next update cannot return the actor to the old position.
    local flying=r.scopes.movement_fly~=nil
    if flying then r:Drop("movement_fly")end
    local ok,err=pcall(function()
        actor:PivotTo(pivot)
        root.AssemblyLinearVelocity=Vector3.zero root.AssemblyAngularVelocity=Vector3.zero
    end)
    if flying then r:Sync()end
    assert(ok,err)
    r.ctx.report("Teleported beside "..selected.DisplayName)
end
function Misc.action(r,id)
    if ShopPurchases.action(r,id)then return true
