local LuaFeatures = (function()
-- Cooperative local script loader. It cannot sandbox or forcibly unload arbitrary executor code.
local Lua={name="Lua loader"}
local folder="ReforgedEnhancements/scripts"
local function valid(name)return type(name)=="string"and #name<=100 and not name:find("..",1,true)and name:match("^[%w_. %-]+%.lua[u]?$")~=nil end
local function refresh(r)
    assert(type(isfolder)=="function"and type(makefolder)=="function"and type(listfiles)=="function"and type(readfile)=="function","Executor filesystem unavailable")
    if not isfolder(folder)then makefolder(folder)end
    local options=FeatureSpec.controls.lua_selected_script.options table.clear(options)
    for _,path in ipairs(listfiles(folder))do local name=path:gsub("\\","/"):match("([^/]+)$")if valid(name)then options[#options+1]=name end end table.sort(options)
end
local function load(r,name)
    assert(valid(name),"Select a local .lua/.luau script")assert(not r.loader.loaded[name],"Script is already loaded")
    local path=folder.."/"..name assert(isfile(path),"Script file not found")assert(type(loadstring)=="function","Local compiler unavailable")
    local chunk,err=loadstring(readfile(path),"@"..path)assert(chunk,err)
    if type(setfenv)=="function"then setfenv(chunk,setmetatable({},{__index=getfenv(chunk)}))end
    local life=r.ctx.life:Scope()local record={life=life,name=name,starting=true}r.loader.loaded[name]=record
    life:Defer(function()r.loader.loaded[name]=nil end)
    life:Spawn(function()
        local ok,result=pcall(chunk,{Lifecycle=life,Notify=function()return false end})
        record.starting=false
        if not ok then life:Cleanup()r.ctx.report("Script failed: "..tostring(result):sub(1,150))return end
        if type(result)=="function"then record.unload=result
        elseif type(result)=="table"and type(result.Unload)=="function"then record.unload=function()result:Unload()end end
        if record.unload then life:Defer(record.unload)end
        r.ctx.report(name..(record.unload and " loaded; explicit unload supported"or " loaded; arbitrary script resources cannot be forcibly unloaded"))
    end)
end
function Lua.update(r)
    if r.loader then return end
    refresh(r)r.loader={loaded={},autoload={}}
    r.ctx.life:Defer(function()table.clear(r.loader.loaded)table.clear(r.loader.autoload)end)
    local path=folder.."/autoload.json"
    if isfile(path)then
        local ok,raw=pcall(function()return r.ctx.http:JSONDecode(readfile(path))end)
        if ok and type(raw)=="table"then for _,name in ipairs(raw)do if valid(name)and isfile(folder.."/"..name)and not table.find(r.loader.autoload,name)then r.loader.autoload[#r.loader.autoload+1]=name end end end
    end
    for _,name in ipairs(r.loader.autoload)do
        local ok,err=pcall(load,r,name)if not ok then r.ctx.report("Lua autoload failed: "..tostring(err):sub(1,120))end
    end
end
function Lua.action(r,id)
    if not id:match("^evidence:Settings:lua:")then return false end
    Lua.update(r)local name=r:Value("lua_selected_script")
    if id:match(":refresh list$")then refresh(r)r.ctx.report("Local scripts refreshed")
    elseif id:match(":load$")then load(r,name)
    elseif id:match(":unload$")then
        local record=r.loader.loaded[name]assert(record,"Selected script is not loaded")
        assert(record.unload or record.starting,"This script returned no unload function; arbitrary resources cannot be forcibly stopped")
        record.life:Cleanup()r.ctx.report("Script unloaded: "..name)
    elseif id:match(":add autoload$")or id:match(":remove autoload$")then
        assert(valid(name)and isfile(folder.."/"..name),"Select a local script")local index=table.find(r.loader.autoload,name)
        if id:match(":add autoload$")and not index then table.insert(r.loader.autoload,name)elseif id:match(":remove autoload$")and index then table.remove(r.loader.autoload,index)end
        writefile(folder.."/autoload.json",r.ctx.http:JSONEncode(r.loader.autoload))r.ctx.report("Script autoload list saved")
    else return false end
    return true
end
Lua.validName=valid
return Lua

end)()
