local WorldFeatures = (function()
local World={name="World"}
local faces={"SkyboxBk","SkyboxDn","SkyboxFt","SkyboxLf","SkyboxRt","SkyboxUp"}
local function night(lighting)return lighting.ClockTime<6 or lighting.ClockTime>=18 end
local function skyStatus(r,scope)
    if r.Errors.skybox_assets then r.ctx.report(r.Errors.skybox_assets)
    elseif scope.loaded then r.ctx.report("Skybox loaded: "..scope.preset..(night(r.ctx.lighting)and " • night may hide textures; check Clock Time"or ""))
    else r.ctx.report("Loading skybox: "..scope.preset)end
