    end
    -- GlobalShadows is a direct boolean rather than an override toggle. An absent
    -- preference leaves the game alone; explicit true/false persists after edits.
    r:Use("lighting_bool_GlobalShadows",r.ctx.values().lighting_bool_GlobalShadows~=nil,function(scope)r:Hold(scope,lighting,"GlobalShadows",v("lighting_bool_GlobalShadows"))end)
    r:Use("lighting_technology",v("lighting_technology")~="Game default",function(scope)
