    r:Use("skybox_enabled",v("skybox_enabled"),function(scope)
        local selected=v("skybox_value")if selected=="Storm"then selected="stormy"end
        local values=assert(FeatureSpec.skyboxes[selected],"No source asset mapping for "..selected)
        -- More than one direct Sky can exist; editing only the first does not
        -- guarantee that the renderer's chosen Sky receives the selected preset.
        local skies={}
        for _,object in ipairs(lighting:QueryDescendants("Sky"))do if object.Parent==lighting then skies[#skies+1]=object end end
        if #skies==0 then skies[1]=target(r,"skybox_enabled","Sky",scope)end
        scope.target=skies[1]
        for _,object in ipairs(skies)do for i,key in ipairs(faces)do r:Hold(scope,object,key,"rbxassetid://"..tostring(values[i]))end end
