    for _,key in ipairs({"Gui","Settings","Report","refresh","slider","drag","tab","popupAnchor","popupTween","popupBuilding","StorageError","ColorPicker","ColorDraft","RegisterColor","GetColor","OpenColor","CreateColorSwatch","Features","SetFeature","FeatureValue","featureChanged","Keybinds","GetKeybindRows","SetBindMode","Notify","Status"}) do App[key]=nil end
