local function validKey(key)
    local ok,value=pcall(function() return Enum.KeyCode[key] end)
    return ok and value~=nil and key~="Unknown" and key~="None" and key~="Escape" and key~="Backspace"
end
local bindCatalog=Keybinds.catalog(Schema,FeatureSpec)
local ioFunctions={isfolder=isfolder,makefolder=makefolder,isfile=isfile,readfile=readfile,writefile=writefile,listfiles=listfiles}
local storageError, storageReady
local function ensureStorage()
    if storageReady then return end
    for _,key in ipairs({"isfolder","makefolder","isfile","readfile","writefile","listfiles"}) do
        assert(type(ioFunctions[key])=="function", "Executor filesystem unavailable: "..key)
    end
    for _,folder in ipairs({State.Root,State.Root.."/configs",State.Root.."/themes"}) do
        if not ioFunctions.isfolder(folder) then ioFunctions.makefolder(folder) end
        assert(ioFunctions.isfolder(folder), "Could not create "..folder)
    end
    storageReady=true
end
local function writeJSON(file,value)
    ensureStorage()
    assert(file:sub(1,#State.Root+1)==State.Root.."/", "Storage must stay inside ReforgedEnhancements")
    local encoded=Http:JSONEncode(value)
    local old=ioFunctions.isfile(file) and ioFunctions.readfile(file) or nil
    local ok,err=pcall(function()
        ioFunctions.writefile(file,encoded)
        assert(ioFunctions.readfile(file)==encoded,"Save verification failed")
    end)
    if not ok then if old then pcall(ioFunctions.writefile,file,old) end error(err,0) end
end
local function readJSON(file)
    ensureStorage()
    return Http:JSONDecode(ioFunctions.readfile(file))
end
local function names(kind)
    ensureStorage()
    local result={}
    for _,file in ipairs(ioFunctions.listfiles(State.Root.."/"..kind)) do
        local name=file:gsub("\\","/"):match("([^/]+)%.json$")
        if State.validName(name) then result[#result+1]=name end
    end
    table.sort(result)
    return result
end
local settings=State.clean({},validKey)
local autoload
do
    local ok,err=pcall(function()
        ensureStorage()
        if ioFunctions.isfile(State.Root.."/ui.json") then
            local data=readJSON(State.Root.."/ui.json")
            settings=State.clean(data.ui,validKey)
            if State.validName(data.autoload) then autoload=data.autoload end
        end
        if autoload and ioFunctions.isfile(State.path("configs",autoload)) then
            settings=State.decodeProfile(readJSON(State.path("configs",autoload)),validKey)
        end
    end)
    if not ok then storageError=tostring(err) end
end
local colors=Style.resolve(settings)
