local function featureValue(id)return FeatureSpec.value(featureValues(),id)end
local function setFeature(id,value)
    if id=="ambience_enabled"and value==true and FeatureSpec.value(settings.featureValues,"ambience_value")=="Heavy Rain"then
        if App.Report then App.Report("Heavy Rain unavailable; choose a source ambience first")end
        return
    end
    local clean=State.cleanFeatures({[id]=value},validKey)
    assert(clean[id]~=nil,"Invalid or unsupported feature setting: "..tostring(id))
    settings.featureValues[id]=clean[id]
    if id=="animation_player_custom_input"and clean[id]:find("%S")then
        settings.featureValues.animation_player_value="custom"
    end
    if id=="ambience_value"and clean[id]=="Heavy Rain"then settings.featureValues.ambience_enabled=false end
    if keybindManager then keybindManager:Override(id)end
    if App.refresh then App.refresh()end
    if App.featureChanged then App.featureChanged()end
end
