local function forgetTree(target)
    local function forget(object)
        local cleanup=App.controlCleanups[object]if cleanup then App.controlCleanups[object]=nil cleanup()end
        if object:IsA("UIScale") then local index=table.find(scaledRoots,object) if index then table.remove(scaledRoots,index) end end
        App.paints[object]=nil App.fontObjects[object]=nil
        App.ColorSwatches[object]=nil
        for fn,owner in pairs(App.controlOwners)do if owner==object then
            App.controlOwners[fn]=nil local index=table.find(App.controls,fn)if index then table.remove(App.controls,index)end
        end end
        if App.controlsById and App.controlsById[object.Name]==object then App.controlsById[object.Name]=nil end
        App.Lifecycle:Release(object)
    end
    local children=target:GetDescendants()
    for _,child in ipairs(children) do forget(child) end
    forget(target)
