    -- AbsolutePosition includes ScreenGui's inset offset (currently -58 px).
    -- Convert it back to this parent before assigning a local Position.
    local pos=anchorPosition-gui.AbsolutePosition
    height=math.min(height,(size.Y-24)/scale.Scale)
    local y=pos.Y+anchorHeight+(below and scale.Scale or 2)
    if below then height=math.max(1,math.min(height,(size.Y-y-2)/scale.Scale))
    else y=math.clamp(y,2,math.max(2,size.Y-height*scale.Scale-2))end
    height=math.max(1,math.floor(height))
    popup=frame(gui,{Name="Popup",Position=screenOffset(math.clamp(pos.X,2,math.max(2,size.X-width*scale.Scale-2)),y),Size=UDim2.fromOffset(width,0),ClipsDescendants=true,ZIndex=50})
