    assert(ColorPicker.hex(spec.defaultHex),"Use a six-digit default colour")
    if App.ColorDefinitions[spec.id]then return spec.id end
    local definition={id=spec.id,title=spec.title or spec.id,hint=spec.hint,role=spec.role,defaultHex=ColorPicker.hex(spec.defaultHex),alpha=spec.transparency~=nil,defaultTransparency=State.number(spec.transparency,0,1,4)or 0}
    App.ColorDefinitions[spec.id]=definition return spec.id
end
local function getColor(id,draft)
    local definition=assert(App.ColorDefinitions[id],"Unregistered colour: "..tostring(id))
    if draft and App.ColorDraft and App.ColorDraft.id==id then return {hex=App.ColorDraft.hex,transparency=App.ColorDraft.transparency or 0,customized=true}end
    if definition.role then return {hex=settings[definition.role],transparency=0}end
    local saved=settings.featureColors[id]
    return {hex=saved and saved.hex or definition.defaultHex,transparency=definition.alpha and (saved and saved.transparency or definition.defaultTransparency)or 0,customized=saved~=nil}
