openColor=function(id,anchor)
    if App.ColorPicker and App.ColorPicker.Id==id then closePopup()return end
    local definition=assert(App.ColorDefinitions[id],"Unregistered colour")
    local value=getColor(id,false)
    local pop=panel(anchor,ColorPicker.height(definition.alpha),ColorPicker.Width)
    local picker=ColorPicker.mount({root=pop,make=make,text=text,button=button,entry=entry,connect=connect,close=closePopup},{
        title=definition.title,hex=value.hex,transparency=value.transparency,allowTransparency=definition.alpha,
        onPreview=function(draft)
            App.ColorDraft={id=id,role=definition.role,hex=draft.hex,transparency=draft.transparency}
            refreshSwatches()
            -- Coalesce appearance work into a scheduled turn instead of repainting
            -- every panel at the raw mouse polling rate. The picker itself is immediate.
            if not previewTask then previewTask=App.Lifecycle:Delay(0,function()previewTask=nil if App.refresh then App.refresh()end end)end
        end,
        onCancel=function()stopPreviewTask()App.ColorDraft=nil if App.refresh then App.refresh()end end,
        onCommit=function(selected)
            stopPreviewTask()
            App.ColorDraft=nil
            if definition.role then settings[definition.role]=selected.hex settings.theme="Custom"
            else settings.featureColors[id]={hex=selected.hex,transparency=definition.alpha and selected.transparency or 0}end
            changed()if App.refresh then App.refresh()end
        end,
    })
    picker.Id=id App.ColorPicker=picker App.popupBuilding=false
end
