local function slider(parent,label,get,set,min,max,decimals,props)
    local holder=frame(parent,props or {Size=UDim2.new(1,0,0,15),Active=true})
    paint(holder,"BackgroundColor3","control") paint(holder,"BorderColor3","controlBorder")
    local fill=frame(holder,{BorderSizePixel=0,Size=UDim2.new(0,0,1,0)}) paint(fill,"BackgroundColor3","accentFill")
    local caption=text(holder,label,{TextXAlignment=Enum.TextXAlignment.Center,Size=UDim2.fromScale(1,1),ZIndex=3,TextStrokeTransparency=Style.SliderStrokeTransparency,TextStrokeColor3=Color3.new(0,0,0)})
    local number=text(holder,"",{Name="SliderValue",Position=UDim2.new(1,-63,0,0),Size=UDim2.new(0,60,1,0),BackgroundTransparency=1,TextXAlignment=Enum.TextXAlignment.Right,TextStrokeTransparency=Style.SliderStrokeTransparency,TextStrokeColor3=Color3.new(0,0,0),Active=false,Interactable=false,ZIndex=5})
    number.BorderSizePixel=0
    local activeTween,lastValue
    App.controlCleanups[holder]=function()if activeTween then releaseTween(activeTween)activeTween=nil end end
    local function refresh()
        local value=get()
        caption.Text=label..":" caption.Size=UDim2.new(1,-63,1,0)
        number.Text=tostring(value)
        if value~=lastValue then
            local size=UDim2.new((value-min)/(max-min),0,1,0)
            if activeTween then releaseTween(activeTween)activeTween=nil end
            if lastValue==nil then fill.Size=size else activeTween=newTween(fill,TweenInfo.new(0.07),{Size=size})activeTween:Play()end
            lastValue=value
        end
    end
    controlRefresh(holder,refresh)
    connect(holder.InputBegan,function(input)
        if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then
            local function update(x) set(State.number(min+(max-min)*math.clamp((x-holder.AbsolutePosition.X)/holder.AbsoluteSize.X,0,1),min,max,decimals)) App.refresh() end
            App.slider={update=update,input=input,touch=input.UserInputType==Enum.UserInputType.Touch} update(input.Position.X)
        end
    end)
    refresh()
    return holder
end
