local lastPalette,lastFont
local function refresh()
    if not App.alive then return end
    local visible=appearance()
    local palette=table.concat({visible.background,visible.main,visible.accent,visible.outline,visible.text},":")
    if palette~=lastPalette then
        colors=Style.resolve(visible)
        local pickerColors=App.ColorPicker and Style.resolve(settings)or colors
        local function inPicker(object)
            local root=App.ColorPicker and App.ColorPicker.Root
            while root and object do if object==root then return true end object=object.Parent end
            return false
        end
        for object,properties in pairs(App.paints) do
            if object.Parent then local source=inPicker(object) and pickerColors or colors for property,role in pairs(properties) do object[property]=source[role] end end
        end
        lastPalette=palette
    end
    if settings.font~=lastFont then
        for object in pairs(App.fontObjects) do if object.Parent then object.Font=Enum.Font[settings.font] end end
        lastFont=settings.font
    end
    overlay.Visible=settings.overlay
    overlay.BackgroundTransparency=1-settings.overlayOpacity/100
    local rows=keybindManager and keybindManager:Rows(settings.overlayMode,window.Visible)or {}
    for _,row in pairs(App.KeybindEntries)do row.Visible=false end
    for index,entry in ipairs(rows)do
        local row=App.KeybindEntries[entry.id]row.Visible=true row.Position=UDim2.fromOffset(4,20+(index-1)*18)
        row.Text="["..entry.key.."] "..entry.label..(entry.mode~="Always"and (" ("..entry.mode..")")or "")
        row.TextColor3=entry.highlighted and colors.accent or Color3.fromRGB(145,145,153)
        row.TextTransparency=0
    end
    overlayHeader.TextTransparency=0
    overlay.Size=UDim2.fromOffset(218,#rows>0 and 25+18*#rows or 22)
    blur.Size=settings.blur blur.Parent=settings.blur>0 and window.Visible and Lighting or nil
    for _,fn in ipairs(App.controls) do fn() end
    for name,b in pairs(tabButtons) do b.BackgroundColor3=name==App.tab and colors.control or colors.main end
    refreshSwatches()
    if features then features:Sync()end
end
