local function renderControls(parent,group,controls,afterRow)
    local ordered=table.clone(controls or group.controls)
    table.sort(ordered,function(a,b)return (a.order or 0)<(b.order or 0)end)
    local byId,pairById,drawn={},{},{}
    for _,control in ipairs(ordered)do byId[control.id]=control end
    for _,pair in ipairs(group.pairs or {})do
        if byId[pair[1]] and byId[pair[2]] then pairById[pair[1]]=pair pairById[pair[2]]=pair end
    end
    local order=0
    for _,control in ipairs(ordered)do if not drawn[control.id] then
        order+=2
        local pair=pairById[control.id]
        if pair then
            local holder=frame(parent,{Name="Pair:"..pair[1],Size=UDim2.new(1,0,0,19),BackgroundTransparency=1,BorderSizePixel=0,LayoutOrder=order})
            for index,id in ipairs(pair)do
                local row=disabled(holder,byId[id])
                row.Size=UDim2.new(0.5,-1,0,19) row.Position=UDim2.new((index-1)*0.5,index-1,0,0)
                drawn[id]=true
            end
        else
            local row=disabled(parent,control) row.LayoutOrder=order drawn[control.id]=true
            if afterRow then afterRow(control,row) end
        end
    end end
end
local function buttonPair(parent,leftLabel,leftFn,rightLabel,rightFn,height)
    height=height or 19
    local row=frame(parent,{Size=UDim2.new(1,0,0,height),BackgroundTransparency=1,BorderSizePixel=0})
