connect(Input.InputBegan,function(input,processed)
    if featureCapture then
        if input.KeyCode==Enum.KeyCode.Escape then featureCapture=nil refresh()return end
        local key=input.KeyCode.Name
        if validKey(key)or key=="Backspace"then local id=featureCapture featureCapture=nil setFeature(id,key=="Backspace"and "None"or key)end
        return
    end
    if capture then
        if input.KeyCode==Enum.KeyCode.Escape then capture=nil report("Key capture cancelled") return end
        local key=input.KeyCode.Name
        if validKey(key) then settings.menuKey=key capture=nil refresh() changed() report("Menu bind changed to "..key) end
        return
    end
    if input.KeyCode==Enum.KeyCode.Escape then
        if popup then closePopup() elseif App.drag then App.drag=nil dragOutline.Visible=false end return
    end
    if popup and input.UserInputType==Enum.UserInputType.MouseButton1 then
        local p,s=popup.AbsolutePosition,popup.AbsoluteSize local x,y=input.Position.X,input.Position.Y
        if x<p.X or x>p.X+s.X or y<p.Y or y>p.Y+s.Y then closePopup() end
    end
    if Input:GetFocusedTextBox() then return end
    if not processed then
        keybindManager:Begin(input.KeyCode.Name)
    end
    if not processed and input.KeyCode.Name==settings.menuKey then setOpen(not window.Visible) end
end)
connect(Input.InputChanged,function(input)
    if App.ColorPicker then App.ColorPicker:InputChanged(input)end
    local move=input.UserInputType==Enum.UserInputType.MouseMovement
    local slide=App.slider
    if slide and (move and not slide.touch or input==slide.input) then slide.update(input.Position.X) end
    local d=App.drag
    if d and (move and not d.touch or input==d.input) then
        local desired=clampPosition(d.position+Vector2.new(input.Position.X,input.Position.Y)-d.start,d.target.AbsoluteSize)
        d.desired=desired
        local target=d.preview and dragOutline or d.target target.Position=UDim2.fromOffset(desired.X,desired.Y)
    end
end)
local function finishInput(input)
    if keybindManager and input.KeyCode then keybindManager:End(input.KeyCode.Name)end
    if App.ColorPicker then App.ColorPicker:InputEnded(input)end
    if input.UserInputType~=Enum.UserInputType.MouseButton1 and input.UserInputType~=Enum.UserInputType.Touch then return end
    if App.slider and (not App.slider.touch or App.slider.input==input) then App.slider=nil end
    local d=App.drag
    if d and (not d.touch or d.input==input) then
        if d.desired then
            d.target.Position=UDim2.fromOffset(d.desired.X,d.desired.Y)
            if d.target==window then settings.windowX=d.desired.X settings.windowY=d.desired.Y else settings.overlayX=d.desired.X settings.overlayY=d.desired.Y end
            changed()
        end
        App.drag=nil dragOutline.Visible=false
    end
end
connect(Input.InputEnded,finishInput)
connect(Input.WindowFocusReleased,function()focused=false App.slider=nil App.drag=nil capture=nil featureCapture=nil if keybindManager then keybindManager:Reset()end dragOutline.Visible=false closePopup()refresh()end)
